import{_ as l,c as e,o as a,al as t}from"./chunks/framework.CT7RwC5a.js";const p=JSON.parse('{"title":"Battery-Chemistry Overview","description":"","frontmatter":{},"headers":[],"relativePath":"uk/power_systems/battery_chemistry.md","filePath":"uk/power_systems/battery_chemistry.md"}'),r={name:"uk/power_systems/battery_chemistry.md"};function o(s,i,n,u,h,c){return a(),e("div",null,i[0]||(i[0]=[t('<h1 id="battery-chemistry-overview" tabindex="-1">Battery-Chemistry Overview <a class="header-anchor" href="#battery-chemistry-overview" aria-label="Permalink to &quot;Battery-Chemistry Overview&quot;">​</a></h1><p>This section provides a comparative overview of several different battery types (in particular LiPo and Li-Ion) and some useful battery glossary terms.</p><h2 id="lipo-vs-li-ion" tabindex="-1">LiPo vs Li-Ion <a class="header-anchor" href="#lipo-vs-li-ion" aria-label="Permalink to &quot;LiPo vs Li-Ion&quot;">​</a></h2><ul><li>Акумулятори Li-Ion мають вищу щільність енергії, ніж пакети акумуляторів Lipo, але це відбувається за рахунок нижчих швидкостей розряду та збільшення вартості акумулятора.</li><li>Акумулятори LiPo легко доступні і можуть витримати вищі розрядні струми, які є типовими для мультироторних літальних апаратів.</li><li>Вибір потрібно здійснювати на основі транспортного засобу та місії, яку виконують. Якщо абсолютна витривалість є метою, то є більше користі від переходу на літій-іонний акумулятор, але, так само, потрібно бути обережним. Отже, рішення повинно бути прийняте на підставі факторів, що оточують польот.</li></ul><h3 id="lipo" tabindex="-1">LiPo <a class="header-anchor" href="#lipo" aria-label="Permalink to &quot;LiPo&quot;">​</a></h3><p>Advantages:</p><ul><li>Дуже поширене</li><li>Широкий асортимент розмірів, ємностей та напруг</li><li>Недорогий</li><li>Високі розрядні ставки відносно ємності (високі рейтинги C)</li><li>Вищі показники заряду</li></ul><p>Недоліки:</p><ul><li>Низька (відносна) щільність енергії</li><li>Якість може відрізнятися від великої кількості постачальників</li></ul><h3 id="li-ion" tabindex="-1">Li-Ion <a class="header-anchor" href="#li-ion" aria-label="Permalink to &quot;Li-Ion&quot;">​</a></h3><p>Advantages:</p><ul><li>Набагато вища енергетична щільність (до 60% вище)</li></ul><p>Недоліки:</p><ul><li>Не так часто</li><li>Набагато дорожче</li><li>Не доступно для великих розмірів та конфігурацій</li><li>Усі клітини відносно малі, тому більші пакети складаються з багатьох клітин, зв&#39;язаних послідовно і паралельно, щоб створити необхідне напругу та ємність</li><li>Нижчі рівні розряду відносно розміру батареї (рейтинг C)</li><li>Складніше адаптуватися до транспортних засобів, які потребують великих струмів</li><li>Нижчі тарифи зарядки (відносно потужності)</li><li>Вимагає більш суворого моніторингу температури під час заряджання та розряджання</li><li>Вимагає змін налаштувань на ESC для використання максимальної ємності (&quot;стандартні&quot; налаштування низької напруги ESC занадто високі).</li><li>При майже порожньому акумуляторі напруга така, що можлива різниця близько 3 В між Lipo та Li-ion (при використанні акумулятора 6S). Це може мати наслідки для очікувань з тяги.</li></ul><h2 id="c-реитинги" tabindex="-1">C Рейтинги <a class="header-anchor" href="#c-реитинги" aria-label="Permalink to &quot;C Рейтинги&quot;">​</a></h2><ul><li>Рейтинг C - це просто кратне заявленої ємності будь-якого типу батареї.</li><li>Оцінка C є важливою (і відрізняється) як для швидкості заряду, так і для швидкості розряду. <ul><li>Наприклад, батарея на 2000 мАг (незалежно від напруги) з розрядом 10C може безпечно і безперервно витікати 20 амперів струму (2000/1000=2Аг x 10C = 20 амперів).</li></ul></li><li>C рейтинги завжди надаються виробником (часто на зовнішній частині батарейного блоку). Хоча їх можна фактично обчислити, вам потрібно кілька частин інформації, і виміряти внутрішній опір клітинок.</li><li>Акумулятори LiPo завжди матимуть вищий рейтинг C, ніж акумулятор Li-Ion. Це пов&#39;язано з типом хімії, а також з внутрішнім опором на кожну клітину (що пов&#39;язано з типом хімії), що призводить до вищих рівнів розряду для акумуляторів LiPo.</li><li>Дотримання виробників рекомендацій щодо обох рейтингів C для заряду та розряду є дуже важливим для здоров&#39;я вашого акумулятора та безпечної експлуатації вашого транспортного засобу (тобто запобігання пожеж, &quot;надування&quot; пакетів та інших неоптимальних станів під час зарядки та розрядки).</li></ul><h2 id="енергетична-щільність" tabindex="-1">Енергетична щільність <a class="header-anchor" href="#енергетична-щільність" aria-label="Permalink to &quot;Енергетична щільність&quot;">​</a></h2><ul><li>Енергетична щільність - це скільки енергії може бути збережено відносно ваги батареї. Зазвичай вимірюється і порівнюється у ват-годинах на кілограм (Вт•год/кг). <ul><li>Ват-години просто розраховуються шляхом множення номінальної (тобто не повністю зарядної напруги) на ємність, наприклад, 3,7 В х 5 Аг = 18,5 Вт-г. Якби у вас був акумулятор на 3 клітки, ваш пакет був би 18,5 Вт·год X 3 = 55 Вт збереженої енергії.</li></ul></li><li>Коли ви враховуєте вагу батареї, ви розраховуєте енергетичну щільність, взявши ват-години і поділивши їх на вагу. <ul><li>Наприклад, 55 Вт годин поділено на (вага батареї в грамах поділена на 1000). Припускаючи, що ця батарея важить 300 грам, тоді 55/(300/1000)=185 Вт·г/кг.</li></ul></li><li>Це число 185 Вт/кг було б на дуже високому рівні для акумулятора LiPo. Літій-іонна батарея, з іншого боку, може досягти 260 Вт·год/кг, що означає, що на кожний кілограм батареї на борту ви можете переносити на 75 Вт·год більше. <ul><li>Якщо ви знаєте, скільки ватт потрібно вашому транспортному засобу для польоту (що може показати модуль поточного батареї), ви можете віднести це збільшене зберігання без додаткової ваги до збільшеного часу польоту.</li></ul></li></ul>',18)]))}const m=l(r,[["render",o]]);export{p as __pageData,m as default};
